package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name, usage, def string
	b                *bool
	s                *string
}

type Parser struct {
	name  string
	flags []*flag
	Args  []string // positional arguments, filled by Parse
}

func New(name string) *Parser { return &Parser{name: name} }

// Bool defines a boolean flag that is false unless given.
func (p *Parser) Bool(name, usage string) *bool {
	v := new(bool)
	p.flags = append(p.flags, &flag{name: name, usage: usage, b: v})
	return v
}

// String defines a flag that takes a value, as --name value or --name=value.
func (p *Parser) String(name, def, usage string) *string {
	v := &def
	p.flags = append(p.flags, &flag{name: name, usage: usage, def: def, s: v})
	return v
}

// Usage builds the help message from the defined flags.
func (p *Parser) Usage() string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "Usage: %s [flags] [args...]\n\nFlags:\n", p.name)
	for _, f := range p.flags {
		name := "--" + f.name
		if f.s != nil {
			name += " <value>"
		}
		fmt.Fprintf(&sb, "  %-22s %s", name, f.usage)
		if f.def != "" {
			fmt.Fprintf(&sb, " (default %q)", f.def)
		}
		sb.WriteByte('\n')
	}
	fmt.Fprintf(&sb, "  %-22s %s\n", "--help", "show this help")
	return sb.String()
}

// Parse reads args (normally os.Args[1:]). Flags and positional arguments
// may be mixed; everything after "--" is positional.
func (p *Parser) Parse(args []string) error {
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			p.Args = append(p.Args, args[i+1:]...)
			return nil
		}
		if a == "-" || !strings.HasPrefix(a, "-") {
			p.Args = append(p.Args, a)
			continue
		}
		name, val, hasVal := strings.Cut(strings.TrimLeft(a, "-"), "=")
		if name == "h" || name == "help" {
			return ErrHelp
		}
		var f *flag
		for _, c := range p.flags {
			if c.name == name {
				f = c
			}
		}
		if f == nil {
			return fmt.Errorf("unknown flag: %s", a)
		}
		if f.b != nil {
			*f.b = true
			if hasVal {
				var err error
				if *f.b, err = strconv.ParseBool(val); err != nil {
					return fmt.Errorf("invalid boolean for --%s: %q", name, val)
				}
			}
			continue
		}
		if !hasVal {
			if i++; i == len(args) {
				return fmt.Errorf("flag needs a value: %s", a)
			}
			val = args[i]
		}
		*f.s = val
	}
	return nil
}
